export const BODY: string = "\n<p>التمويه والتبكسيل يخفيان الأشياء، لكنهما ليسا الأداة نفسها. أحدهما ينعّم المنطقة حتى تتحول إلى غسل ناعم من اللون، بينما الآخر يستبدلها بكتل كبيرة.</p>\n<p>الفرق مهم عندما تكون الخصوصية على المحك. الأسلوب الذي يبدو خاضعًا للرقابة قد يترك وجهًا معروفًا أو كلمة مقروءة، والاختيار الخاطئ قد يكشف ما أردت إخفاءه بالضبط.</p>\n<p>يقارن هذا المقال الأسلوبين مباشرة: كيف يعملان وكيف يبدوان وأيهما أكثر أمانًا للوجوه والنصوص، ومتى تجمعهما لرقابة صحيحة. وإذا أردت رؤية الفرق بصورك الخاصة، جرّب <a href=\"/ar/tammih-wa-tabaksul-as-sura/\">أداة تمويه وتبكسيل الصورة</a>.</p>\n<h2 id=\"how-each-method-works\">كيف يعمل كل أسلوب</h2>\n<p>التمويه يمتص ألوان البكسلات المجاورة. الحواف الحادة تذوب والنص يصبح غير مقروء والوجوه تفقد ملامحها كلما زادت القوة.</p>\n<p>أما التبكسيل فيستبدل المنطقة بكتل من اللون الواحد. كل كتلة هي متوسط البكسلات تحتها، فتختفي كل التفاصيل الدقيقة ويبقى فسيفساء خشن. التمويه يحافظ على إحساس بالأشكال الأصلية، بينما التبكسيل يدمر الأشكال.</p>\n<h2 id=\"how-they-look\">كيف يبدوان جنبًا إلى جنب</h2>\n<p>المنطقة المموّهة تبدو ناعمة وطبيعية. تمتزج مع الصورة، ولهذا يكون التمويه شائعًا للخلفيات ولإخفاء الهوية بنعومة في البورتريه.</p>\n<p>أما المنطقة المبكسلة فتبدو رقابة متعمدة. الفسيفساء تشير للمشاهد إلى أن شيئًا أُخفي عمدًا، وهذا مفيد في الصحافة والسياقات القانونية. ولصورة تريدها أن تبدو جيدة، التمويه أفضل؛ ولصورة تكون الرقابة نفسها هي المقصود، التبكسيل أفضل.</p>\n<h2 id=\"safety-comparison\">أي الأسلوبين أكثر أمانًا؟</h2>\n<p>بالقوة القصوى، كلا الأسلوبين آمن. التمويه القوي والفسيفساء الكبيرة يدمران المعلومات تمامًا، ولا يمكن عكس أي منهما من الملف المصدّر.</p>\n<p>وبالقوة المعتدلة، التبكسيل أكثر أمانًا. الفسيفساء ذات الكتل الكبيرة تدمر أشكال الحروف تمامًا، بينما التمويه المتوسط قد يترك مخططاتها مقروءة. وبالقوة الخفيفة، لا أسلوب آمن. والقاعدة بسيطة: استخدم أقوى إعداد تستطيع تحمله.</p>\n<h2 id=\"hiding-faces\">كيف تخفي الوجوه: التمويه أم التبكسيل؟</h2>\n<p>للوجوه، التبكسيل غالبًا هو الخيار الآمن. الفسيفساء ذات الكتل الكبيرة تدمر العينين والأنف والفم تمامًا، دون ترك شيء للتعرف عليه.</p>\n<p>التمويه القوي يعمل أيضًا للوجوه، لكن يجب أن يكون قويًا حقًا. التمويه الخفيف الذي يترك العينين والابتسامة ظاهرين لا يحمي أحدًا، مهما بدا ناعمًا. وغطِّ الرأس كله بأي حال، لأن خط الشعر والأذنين والذقن تحمل معلومات تعريفية.</p>\n<h2 id=\"hiding-text\">كيف تخفي النصوص والأرقام: التمويه أم التبكسيل؟</h2>\n<p>للنص، يفوز التبكسيل بوضوح. الفسيفساء تدمر أشكال الحروف، بينما التمويه ينعّمها فقط، والدماغ البشري جيد في قراءة الحروف المنعّمة من السياق.</p>\n<p>اللوحة أو العنوان أو كلمة المرور تحتاج تغطية كاملة. حتى رقم واحد مقروء قد يحدد مركبة، وعنوان جزئي قد يضيّق موقعًا بدقة. وغطِّ السطر كله لا الكلمة الحساسة فقط، واستخدم كتلًا كبيرة للنص الكبير ومعتدلة للنص الصغير.</p>\n<h2 id=\"license-plates\">لوحات السيارات وتفاصيل المركبات</h2>\n<p>اللوحة هدف صغير عالي التباين، ومن السهل رقابتها بشكل خاطئ. التمويه الخفيف فوق لوحة يترك الأحرف مقروءة غالبًا بالحجم الكامل.</p>\n<p>التبكسيل بحجم كتلة معتدل هو الأسلوب الموثوق. الكتل تدمر أشكال الأحرف، وتتحول اللوحة إلى صف من المربعات الملونة. وغطِّ اللوحة كاملة، بما فيها رمز المنطقة وأي نص صغير حول الحواف، وراجع وجود لوحة ثانية في الصورة.</p>\n<h2 id=\"documents-and-screens\">المستندات والشاشات والأوراق</h2>\n<p>المستندات تحتوي على نص في أماكن كثيرة: الترويسات والتذييلات والتوقيعات والأختام. سطر واحد مموّه لا يكفي عندما تظهر نفس المعلومات في مكان آخر من الصفحة.</p>\n<p>بكسل كل سطر حساس لا الواضح فقط. الاسم في الترويسة والعنوان في التذييل ورقم الهوية في المتن كلها تحتاج تغطية. ولقطات الشاشة مماثلة: قد تكشف لوحة أسماء عملاء وروابط داخلية وكلمات مرور في لوحات عدة.</p>\n<h2 id=\"backgrounds\">الخلفيات: عندما يكون التمويه أفضل أداة</h2>\n<p>للخلفيات، التمويه هو الخيار الأفضل. التمويه الناعم يجعل الموضوع يبرز مع إبقاء الصورة تبدو طبيعية، وهو تأثير إبداعي لا رقابة.</p>\n<p>تبكسيل خلفية يبدو سيئًا. الفسيفساء تجذب الانتباه إلى نفسها، وتتوقف الصورة عن الشعور كصورة فوتوغرافية وتبدأ كوثيقة خاضعة للرقابة. وللخصوصية، قد تخفي الخلفية المموّهة موقعًا مثل لافتة شارع أو رقم منزل.</p>\n<h2 id=\"reversibility-myths\">هل يمكن عكس الصور الخاضعة للرقابة؟</h2>\n<p>الخوف الشائع هو أن صورة مموّهة أو مبكسلة يمكن إعادة تركيزها بالبرمجيات. عمليًا، الرقابة القوية لا يمكن عكسها، لأن التفاصيل الأصلية لم تعد موجودة.</p>\n<p>التمويه يمتص البكسلات ويتخلص من التفاصيل الدقيقة. وبعد امتصاص التفاصيل، لا يستطيع أي برنامج معرفة البكسلات الأصلية. والتبكسيل أكثر تدميرًا: كل كتلة تستبدل عشرات البكسلات بلون واحد، فتُفقد المعلومات الأصلية مرات عدة.</p>\n<h2 id=\"strength-settings\">إعدادات القوة مقارنة</h2>\n<p>قوة التمويه مقياس ناعم من خفيف إلى قوي. في الطرف الأدنى، تنعم الصورة قليلًا فقط، وفي الطرف الأعلى تتحول إلى غسل من اللون.</p>\n<p>أما حجم كتلة الفسيفساء فمقياس متدرج من صغير إلى كبير. الكتل الصغيرة تحافظ على تلميح تقريبي للشكل، بينما الكتل الكبيرة تختزل المنطقة إلى بضعة مربعات مسطحة. ولنفس مستوى الأمان، الفسيفساء الكبيرة غالبًا أقوى من التمويه المتوسط.</p>\n<h2 id=\"combining-both\">كيف تجمع بين التمويه والتبكسيل</h2>\n<p>لا يجب أن تختار أسلوبًا واحدًا للصورة كلها. ارسم وجهًا بتمويه ولوحة بتبكسيل، مستخدمًا مبدل الوضع بين الضربات.</p>\n<p>هذا الجمع يستغل نقاط قوة كل أسلوب. الوجه يبدو طبيعيًا تحت تمويه قوي، بينما النص يُدمَّر تمامًا بالفسيفساء. واستخدم التمويه للمناطق الكبيرة الناعمة مثل الخلفيات والوجوه، والتبكسيل للتفاصيل الصغيرة الحادة مثل النص والأرقام والرموز الشريطية.</p>\n<h2 id=\"legal-and-ethical\">ملاحظات قانونية وأخلاقية</h2>\n<p>رقابة وجه لا تجعل الصورة آمنة للنشر دائمًا. القوانين حول الخصوصية والموافقة وحقوق الصورة تختلف، والوجه المموّه قد لا يكفي في كل موقف.</p>\n<p>الأطفال يستحقون عناية إضافية. الوجه المموّه أفضل من الظاهر، لكن الخيار الآمن لطفل لا يستطيع إعطاء موافقته هو عدم مشاركة الصورة. وللصحافة، التبكسيل هو المعيار لأنه يشير بوضوح إلى حماية هوية. وعند الشك، اسأل الشخص في الصورة.</p>\n<h2 id=\"when-neither-is-enough\">عندما لا يكفي أي أسلوب</h2>\n<p>أحيانًا الرقابة ليست الإجابة الصحيحة. الصورة التي تكشف موقعًا بخلفيتها أو بياناتها الوصفية أو سياقها قد تحتاج أن تبقى خاصة تمامًا.</p>\n<p>البيانات الوصفية هي الخطر المخفي. الصورة ذات الوجه المموّه قد تحمل إحداثيات GPS تكشف أين التُقطت، فراجع إعدادات التصدير قبل المشاركة. والسياق خطر آخر: وجه مموّه أمام منزل مميز أو لافتة مدرسة أو شعار عمل قد يحدد الشخص حتى مع رقابة مثالية.</p>\n<h2 id=\"choosing-for-screenshots\">كيف تختار للقطات الشاشة</h2>\n<p>لقطات الشاشة نص في الغالب، فالتبكسيل غالبًا هو الأسلوب الصحيح. الفسيفساء تدمر أشكال الحروف، بينما التمويه الناعم قد يترك الكلمات مقروءة.</p>\n<p>استخدم حجم كتلة معتدلًا للقطات الشاشة. النص صغير، فحتى الفسيفساء المتواضعة تدمره تمامًا، والكتل الأكبر ستغطي كثيرًا من الشاشة. وارسم فوق الأسماء وعناوين البريد وكلمات المرور والروابط الداخلية، وصدّر لقطات الشاشة بصيغة PNG.</p>\n<h2 id=\"cheat-sheet\">ورقة الغش لقرارات سريعة</h2>\n<p>استخدم التبكسيل للنص والأرقام والعناوين واللوحات وكلمات المرور. الفسيفساء تدمر الأشكال تمامًا وهي الخيار الآمن لأي شيء مكتوب.</p>\n<p>استخدم تمويهًا قويًا للوجوه عندما تريد أن تبدو الصورة طبيعية، وتمويهًا خفيفًا للخلفيات. واستخدم كلا الأسلوبين معًا عندما تحمل الصورة أنواعًا مختلفة من التفاصيل الحساسة: موّه الوجوه وبكسل النص وراجع الصورة كاملة بالحجم الكامل قبل المشاركة.</p>\n<h2 id=\"blur-vs-pixelate-social\">التمويه أم التبكسيل على وسائل التواصل</h2>\n<p>منصات التواصل تضغط صورك عند رفعها، والضغط يؤثر في التمويه والتبكسيل بشكل مختلف. التمويه الخفيف قد يضعف بعد الضغط، فتعود التفاصيل الحساسة إلى الظهور.</p>\n<p>لوجه يجب إخفاؤه على وسائل التواصل، التبكسيل هو الخيار الآمن. الفسيفساء تنجو من الضغط وإعادة الترميز، بينما التمويه الناعم قد يرقّ بما يكفي ليكشف الوجه. ولخلفية تريد تنعيمها، التمويه هو الخيار الأفضل.</p>\n<p>للخطوات التفصيلية، راجع <a href=\"/ar/blog/kayfiyya-tammih-wa-tabaksul-as-sura/\">كيف تموّه أو تبكسل صورة</a>. وللدليل الكامل، راجع <a href=\"/ar/blog/dalil-tammih-wa-tabaksul-as-suwar/\">تمويه وتبكسيل الصور: الدليل الكامل</a>، ولإزالة بيانات الموقع تمامًا استخدم <a href=\"/ar/izala-bayanat-as-sura/\">أداة إزالة بيانات الصورة</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"ما الأفضل لإخفاء وجه: التمويه أم التبكسيل؟","answer":"التبكسيل أكثر أمانًا غالبًا، لأن كتل الفسيفساء الكبيرة تدمر ملامح الوجه تمامًا. التمويه القوي يعمل أيضًا، لكن يجب أن يكون قويًا حقًا. التمويه الخفيف الذي يترك العينين والابتسامة ظاهرين لا يحمي أحدًا."},{"question":"هل يمكن لأحد إزالة التمويه عن صورة ببرنامج ذكاء اصطناعي؟","answer":"لا إذا كان التمويه قويًا أو الفسيفساء كبيرة. كلا الأسلوبين يدمر تفاصيل البكسلات الأصلية، فلا يبقى شيء ليستعيده البرنامج. التمويه الخفيف جدًا يمكن إعادة تركيزه أحيانًا، فاستخدم قوة كافية."},{"question":"هل أموّه أم أبكسل كلمة مرور في لقطة شاشة؟","answer":"بكسلها، فالفسيفساء بحجم كتلة معتدل تدمر الأحرف تمامًا، بينما التمويه الناعم قد يترك مخططاتها مقروءة. غطِّ حقل كلمة المرور كاملًا لا الأحرف الظاهرة فقط."},{"question":"هل يكفي شريط أسود فوق العينين لإخفاء وجه؟","answer":"لا، فبقية الوجه، بما فيها الأنف والفم وخط الشعر والذقن، تبقى معروفة. غطِّ الرأس كاملًا بتمويه قوي أو فسيفساء كبيرة، وراجع النتيجة بالحجم الكامل."},{"question":"هل يمكنني استخدام التمويه والتبكسيل في الصورة نفسها؟","answer":"نعم، ارسم الوجوه بتمويه قوي والنص أو اللوحات بتبكسيل، مبدلًا الوضع بين الضربات. هذا يستغل نقاط قوة كل أسلوب: وجوه تبدو طبيعية ونص مدمر تمامًا."},{"question":"هل رقابة الصورة تزيل بيانات موقعها أيضًا؟","answer":"لا وحدها، فالرقابة تخفي التفاصيل المرئية، لكن الملف قد يحمل إحداثيات GPS. التصدير من الأداة يزيل وسوم GPS، وأداة إزالة بيانات الصورة تمسح بقية البيانات الوصفية."}];
